                    // detection as ParamEmit's stringParam.
                    bool untyped = false;
                    if (auto dt = psS.getDeclaredType())
                        if (auto tsyn = dt->getTypeSyntax())
                            untyped =
                                tsyn->kind == syntax::SyntaxKind::ImplicitType;
