                        case UHDM::uhdmlogic_net:
                        case UHDM::uhdmarray_net:
                        case UHDM::uhdmstruct_net:
                        case UHDM::uhdmenum_net:
                        case UHDM::uhdmpacked_array_net:
                        case UHDM::uhdmnet_bit:
