                            qv9->VpiFullName(branchPrefix + "." + vname);
                            qv9->VpiParent(asQ);
                            setLoc(qv9, nameSpan(dcl->name.location(), vname));
                            auto* rtQ = s.MakeRef_typespec();
                            rtQ->VpiFullName(branchPrefix + "." + vname);
                            rtQ->VpiParent(qv9);
                            rtQ->Actual_typespec(qts9);
                            qv9->Typespec(rtQ);
                            asQ->Lhs(qv9);
                            stmts->push_back(asQ);
