                        as3->VpiOpType(82);
                        as3->VpiBlocking(true);
                        setLoc(as3, dcl->sourceRange());
                        auto* av3 = s.MakeArray_var();
                        av3->VpiName(vname);
                        av3->VpiFullName(branchPrefix + "." + vname);
                        av3->VpiParent(as3);
                        setLoc(av3, nameSpan(dcl->name.location(), vname));
