                        rta3->VpiParent(av3);
                        rta3->Actual_typespec(ats3);
                        av3->Typespec(rta3);
                        auto* lv3 = s.MakeLogic_var();
                        lv3->VpiFullName(branchPrefix + "." + vname);
                        lv3->VpiParent(av3);
                        setLoc(lv3, nameSpan(dcl->name.location(), vname));
