                        ert3->VpiParent(ats3);
                        ert3->Actual_typespec(lts3);
                        ats3->Elem_typespec(ert3);
                        auto* rtl3 = s.MakeRef_typespec();
                        rtl3->VpiFullName(branchPrefix + "." + vname);
                        rtl3->VpiParent(lv3);
                        rtl3->Actual_typespec(lts3);
                        lv3->Typespec(rtl3);
                        auto* regs3 = s.MakeVariablesVec();
                        regs3->push_back(lv3);
                        av3->Variables(regs3);
                        as3->Lhs(av3);
                        // An INITIALIZED array decl (= '{default: '0}) carries
                        // the pattern as Rhs (operation 75 parented at the
                        // assignment); the pattern VALUE constant stays
                        // UNPARENTED (Surelog). Refs scope at the branch.
